// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { CellProps } from "./cell.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Cell";

// Generate child element class names for the component, should match available style slots
export const CellClasses = {
  root: "exp-textura_cell",
  assetIcon: "exp-textura_cell_asset_icon",
  avatar: "exp-textura_cell_avatar",
  badge: "exp-textura_cell_badge",
  inlineBadge: "exp-textura_cell_inline_badge",
  button: "exp-textura_cell_button",
  chip: "exp-textura_cell_chip",
  iconButton: "exp-textura_cell_icon_button",
  infoBlock: "exp-textura_cell_info_block",
  link: "exp-textura_cell_link",
  number: "exp-textura_cell_number",
  svgIcon: "exp-textura_cell_svg_icon",
  expandToggle: "exp-textura_cell_expand_toggle",
  subRowIndicator: "exp-textura_cell_sub_row_indicator",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: CellProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<CellProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    width: "fill-available",

    [`& .${CellClasses.assetIcon}`]: {
      ...styleSlots?.assetIcon,
    },

    [`& .${CellClasses.avatar}`]: {
      ...styleSlots?.avatar,
    },

    [`& .${CellClasses.badge}`]: {
      ...styleSlots?.badge,
    },

    [`& .${CellClasses.inlineBadge}`]: {
      ...styleSlots?.inlineBadge,
    },

    [`& .${CellClasses.button}`]: {
      ...styleSlots?.button,
    },

    [`& .${CellClasses.chip}`]: {
      ...styleSlots?.chip,
    },

    [`& .${CellClasses.iconButton}`]: {
      ...styleSlots?.iconButton,
    },

    [`& .${CellClasses.infoBlock}`]: {
      width: "100%",
      ...styleSlots?.infoBlock,
    },

    [`& .${CellClasses.link}`]: {
      color: theme.color.content.default,
      ...styleSlots?.link,
    },

    [`& .${CellClasses.number}`]: {
      display: "flex",
      justifyContent: "flex-end",
      width: "100%",
      ...styleSlots?.number,
    },

    [`& .${CellClasses.svgIcon}`]: {
      ...styleSlots?.svgIcon,
    },

    [`& .${CellClasses.expandToggle}`]: {
      display: "inline-flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),

      "& > button": {
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        background: "none",
        border: "none",
        padding: 0,
        cursor: "pointer",
        color: theme.color.content.default,
        "&:focus-visible": {
          outline: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.focus.default}`,
          borderRadius: theme.toRem(theme.border.radius.sm),
        },
      },
      ...styleSlots?.expandToggle,
    },

    [`& .${CellClasses.subRowIndicator}`]: {
      display: "inline-flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[8]),

      "& > svg": {
        flexShrink: 0,
        color: theme.color.content.icon,
      },
      ...styleSlots?.subRowIndicator,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledCell = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<CellProps>((props) => generateStyles(props));
